# la simulation : le schéma « Les figures de style » reçoit une source carte (une ligne par branche)
rep("const $ = id => document.getElementById(id);","/* (p7) le schéma simulé reçoit sa source (le format existant : forme + src texte, une ligne par élément) ; la séance jouée reçoit un schéma sur « Les mouvements du siècle » */ (function(){ const E = DATA.seances[0].ecrans; const m = E.find(e => e.act === 'Les mouvements du siècle'); if (m && !(m.blocs || []).some(b => b.t === 'schema')) m.blocs = (m.blocs || []).concat([{ t: 'schema', bid: 'b-sim-schema', txt: 'Les figures de style', forme: 'carte' }]); })(); DATA.seances.forEach(se => se.ecrans.forEach(e => (e.blocs || []).forEach(b => { if (b.t === 'schema' && !b.src) { b.forme = b.forme || 'carte'; b.src = \"Figures d'analogie : comparaison, métaphore\\nFigures d'opposition : antithèse, oxymore\\nFigures d'insistance : anaphore, hyperbole\"; } if (b.t === 'schema' && b.src && !(b.el || []).length) b.el = b.src.split('\\n').map(x => x.trim()).filter(Boolean); })));\nconst $ = id => document.getElementById(id);",1)
