rep("if (S.atelier && !S.repetition) { const c = document.querySelector('#mur .corpsd');","if (S.atelier && !S.repetition) { const c0 = document.querySelector('#mur .corpsd'); const svgs = document.querySelectorAll('#mur .sch-dessin svg, #mur .sch-dessin table'); if (c0 && svgs.length) svgs.forEach(sv => { const h = sv.getBoundingClientRect().height; if (h < c0.clientHeight * 0.45) { const bi = +sv.closest('[data-bloc]').dataset.bloc; const e = E[S.di]; out.push({ di: S.di, bi, k: 'dense', l: `Schéma « ${(e.blocs[bi] || {}).txt || ''} » trop dense : il n\\'a pas la place (moins de la moitié de la diapo)`, ou: `diapo ${S.di + 1} · « ${e.act} » · bloc ${bi + 1}`, faire: 'donne-lui sa diapo : clic droit sur le bloc → « Couper la diapo ici » (échelle « plein » : un schéma remplit sa diapo, 3.2)', copier: `Schéma « ${(e.blocs[bi] || {}).txt || ''} » (${e.act}) : à mettre seul sur sa diapo.` }); } }); const c = document.querySelector('#mur .corpsd');")
